`default_nettype none
// L2H-IDXSEL s3 (LEAD3-HBM route B, 10-19/20): the die's IDX selector master as a LANDED CLUSTER.
// Port list == the die's current selector master ot_hbm_idx_selector_static_sel (GEN2e3/e4 binding: selected-only face,
// no out_v/out_line emit readback, no observation ports); binding this master is a master rename, no port change.
// Hierarchy (top-down contract: a replicated cluster is hardened once):
//   u_lp = ot_hidx_s3_flat_lp, GENERATED by tools/landed_parent/lp.py (spec tools/landed_parent/specs/hidx_sel_s3.json)
//          from the wires-only flat parent ot_hidx_s3_flat: five clock regions (ctl, q0..q3), 20 landed crossings
//          (ot_pl_land_w/_r, D 4, E 2, +3 edges, shared write rings, no ready/credit/backpressure), 1-bit reset runs;
//   children: ONE hardened quadrant tile ot_hidx_s3_q (x4: lanes + histogram + pack/emit + its 3 SRAMs) and the ctl
//          tile ot_hidx_s3_ctl (control-word pin flops, choose pipeline, reset landing, fault).
// Clocks: clk_ctl -> region ctl, clk_q[q] -> region q<q> (each its own local tree; the die delivers neighbour-matched
// roots and lands in_line[q] / selected_line[q] / selected_v[q] on clk_q[q], op/pass/addr/k/fault on clk_ctl).
// clk_mem stays a port of the die master (die netlist unchanged) and is unloaded: every SRAM runs on its quadrant clock.
// Schedule (tools/hbm_idx_static_calendar.py PIN table registered_s3): sel_in 7 (op word), sel_in_line 2, sel_out 1,
// sel_choose_rt 8 idle edges after every op5 run; op 8 raises the sticky fault (no emit face).
module ot_hbm_idx_selector_s3 #(parameter integer DMUT=0,parameter integer MUT=0)(
 input wire clk_ctl,input wire [3:0] clk_q,input wire [11:0] clk_mem,
 input wire rst_n,input wire [3:0] op,input wire [1:0] pass,
 input wire [7:0] addr,input wire [9:0] k,
 input wire [2367:0] in_line,
 output wire [3:0] selected_v,output wire [2367:0] selected_line,
 output wire fault
);
 ot_hidx_s3_flat_lp #(.DMUT(DMUT),.MUT(MUT)) u_lp(
  .ck_ctl(clk_ctl),.ck_q0(clk_q[0]),.ck_q1(clk_q[1]),.ck_q2(clk_q[2]),.ck_q3(clk_q[3]),
  .rst_n(rst_n),.op(op),.pass(pass),.addr(addr),.k(k),
  .in_line_0(in_line[0+:592]),.in_line_1(in_line[592+:592]),.in_line_2(in_line[1184+:592]),.in_line_3(in_line[1776+:592]),
  .selected_v_0(selected_v[0]),.selected_v_1(selected_v[1]),.selected_v_2(selected_v[2]),.selected_v_3(selected_v[3]),
  .selected_line_0(selected_line[0+:592]),.selected_line_1(selected_line[592+:592]),
  .selected_line_2(selected_line[1184+:592]),.selected_line_3(selected_line[1776+:592]),
  .fault(fault));
endmodule
`default_nettype wire
